pipeline {
    agent any

    environment {
        GROUP_NAME = ''
        PROJECT_NAME = ''
        VERSION = ''
        PORT = '38006'
        REMOTE_HOST = '20.48.1.66'
        REMOTE_USER = 'root'
        REMOTE_CREDENTIALS_ID = 'jenkins-server-ssh-private-key'
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('Asia/Shanghai'))
    }

    stages {
        stage('Git Checkout') {
            steps {
                echo "Checking out code from branch: ${params.Branch}"
                checkout scmGit(
                    branches: [[name: "${params.Branch}"]],
                    extensions: [],
                    userRemoteConfigs: [[
                        credentialsId: 'SSH-KEY-FOR-GITLAB',
                        url: "${GIALAB_ADDRESS}/dengbin/intelligent-prewarning.git"
                    ]]
                )
            }
        }

        stage('Mvn Compile') {
            steps {
                script {
                    def pom = readMavenPom file: 'pom.xml'
                    GROUP_NAME = pom.groupId
                    PROJECT_NAME = pom.artifactId
                    VERSION = pom.version

                    echo "Building project: ${GROUP_NAME}/${PROJECT_NAME}:${VERSION}"
                    sh "mvn -T 4 clean install -Dmaven.test.skip=true -Pdev"
                }
            }
        }

        stage('Build Image') {
            steps {
                script {
                    def imageTag = "${GROUP_NAME}/${PROJECT_NAME}:${VERSION}"

                    // 删除旧镜像（如果存在）
                    sh script: "docker rmi ${imageTag} || true", label: "Remove old image"

                    echo 'Building Docker image...'
                    sh """
                        docker build -t ${imageTag} \\
                            -f "devops/Dockerfile" \\
                            --build-arg group_name=${GROUP_NAME} \\
                            --build-arg project_name=${PROJECT_NAME} \\
                            --build-arg version=${VERSION} \\
                            --build-arg port=${PORT} .
                    """
                    echo "Docker image ${imageTag} built successfully"
                }
            }
        }

        stage('Push Image') {
            steps {
                script {
                    try {
                        sh """
                            echo "Logging into Docker registry..."
                            docker login --username=${DOCKER_REGISTRY_USERNAME} --password=${DOCKER_REGISTRY_PASSWORD} ${DOCKER_REGISTRY}

                            echo "Tagging image..."
                            docker tag ${GROUP_NAME}/${PROJECT_NAME}:${VERSION} ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${TIMESTAMP}

                            echo "Pushing image to registry..."
                            docker push ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${TIMESTAMP}

                            echo "Image pushed to registry: ${GROUP_NAME}/${PROJECT_NAME}:${VERSION}-${TIMESTAMP}"
                        """
                    } catch (Exception e) {
                          echo 'push image failed'
                          echo "Caught exception: ${e.getMessage()}"
                      }
                }
            }
        }

        stage('Deploy to Remote') {
            when {
                expression { return params.DEPLOY }
            }
            steps {
                script {
                    def imageName = "${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${TIMESTAMP}"

                    sshagent([REMOTE_CREDENTIALS_ID]) {
                        sh """
                            ssh -o StrictHostKeyChecking=no ${REMOTE_USER}@${REMOTE_HOST} '
                                set -e
                                echo "Starting deployment of ${imageName}"

                                echo "Logging into Docker registry..."
                                docker login --username=${DOCKER_REGISTRY_USERNAME} \\
                                --password=${DOCKER_REGISTRY_PASSWORD} ${DOCKER_REGISTRY}

                                echo "Pulling image..."
                                docker pull ${imageName}

                                echo "Stopping and removing existing container..."
                                docker rm -f ${PROJECT_NAME} || true

                                echo "Starting new container..."
                                docker run -d \\
                                    --add-host oss-cn-kunming-ynzwy01-d01-a.ops.amscyzx.zwy.yn.cegn.cn:20.12.18.27 \\
                                    --name ${PROJECT_NAME} \\
                                    -p ${PORT}:${PORT} \\
                                    -e TZ=Asia/Shanghai \\
                                    -v /app/logs:/app/logs \\
                                    ${imageName}

                                echo "Deployment completed successfully"
                            '
                        """
                    }
                }
            }
        }
    }
}
